    Object get(Object o,String name)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
    Class<?> boxed(Class<?> c){return c==int.class?Integer.class:c==long.class?Long.class:c==boolean.class?Boolean.class:c;}
    Object call(Object target,String name,Object...args)throws Exception{Class<?> type=target instanceof Class<?> c?c:target.getClass();for(Class<?> c=type;c!=null;c=c.getSuperclass())for(Method m:c.getDeclaredMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){boolean matches=true;for(int i=0;i<args.length;i++)if(args[i]!=null&&!boxed(m.getParameterTypes()[i]).isInstance(args[i]))matches=false;if(matches){m.setAccessible(true);try{return m.invoke(target instanceof Class?null:target,args);}catch(InvocationTargetException ex){throw new RuntimeException(name,ex.getCause());}}}throw new NoSuchMethodException(type+" "+name);}
    void check(boolean yes,String text)throws Exception{Files.writeString(report,(yes?"PASS ":"FAIL ")+text+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);if(!yes)throw new AssertionError(text);}
